<?php
namespace CloudHost247\Ovh\Normalization;
final class CatalogNormalizer
{public function plan(array$p){$hardware=$this->find($p,array('hardware','technicalDetails','specifications'));return array('plan_code'=>(string)($p['planCode']??''),'name'=>(string)($p['invoiceName']??$p['displayName']??$p['planCode']??''),'availability'=>$this->availability($p),'cpu'=>$this->value($hardware,array('cpu','processor','cpuName')),'ram'=>$this->value($hardware,array('memory','ram')),'storage'=>$this->value($hardware,array('storage','disk','drives')),'network'=>$this->value($hardware,array('bandwidth','network','traffic')),'datacenters'=>$this->list($p,array('datacenters','regions','locations')),'operating_systems'=>$this->list($p,array('operatingSystems','os','images')),'configurations'=>$this->configurations($p));}
 private function find($a,$keys){foreach($keys as$k)if(isset($a[$k])&&is_array($a[$k]))return$a[$k];return$a;}private function value($a,$keys){foreach($keys as$k)if(isset($a[$k])&&(is_scalar($a[$k])||is_array($a[$k])))return$a[$k];return null;}private function list($a,$keys){$v=$this->value($a,$keys);return is_array($v)?array_values($v):($v===null?array():array($v));}private function availability($p){foreach(array('available','availability','status')as$k)if(array_key_exists($k,$p))return$p[$k];return'unknown';}private function configurations($p){$out=array();foreach(array('configurations','options','addonFamilies')as$k)if(!empty($p[$k])&&is_array($p[$k]))foreach($p[$k]as$key=>$v)$out[]=array('key'=>(string)$key,'value'=>$v,'source_field'=>$k);return$out;}}
